  const getRankingOptions = () => {
    const totalCandidates = event?.candidates?.length || 0
    const options = []
    
    if (totalCandidates >= 1) {
      options.push({ value: 'winner', label: event?.name || 'Top 1' })
    }

    const getOrdinal = (n) => {
      const rem10 = n % 10
      const rem100 = n % 100
      if (rem10 === 1 && rem100 !== 11) return `${n}st`
      if (rem10 === 2 && rem100 !== 12) return `${n}nd`
      if (rem10 === 3 && rem100 !== 13) return `${n}rd`
      return `${n}th`
    }

    for (let rank = 2; rank <= totalCandidates; rank++) {
      const runnerUpNumber = rank - 1
      const ordinal = getOrdinal(runnerUpNumber)
      options.push({
        value: `${ordinal.toLowerCase()}-runner-up`,
        label: `${ordinal} Runner-up`
      })
    }
    
    return options
  }

  const getWinnerForRanking = (ranking) => {
    const candidateScores = calculateCandidateScores()
    if (!candidateScores.length) return null
    
    let index = 0
    if (ranking === 'winner') {
      index = 0
    } else if (typeof ranking === 'string' && ranking.endsWith('-runner-up')) {
      const numPart = ranking.replace('-runner-up', '').replace(/(st|nd|rd|th)$/i, '')
      const parsed = parseInt(numPart, 10)
      if (!isNaN(parsed) && parsed >= 1) {
        index = parsed
      }
    }
    
    return candidateScores[index] || null
  }

  const getWinnerForAward = (awardId) => {
    const award = specialAwards.find(a => a.id === awardId)
    if (!award) return null
    
    // Get all votes for this award
    const awardVotes = event?.scores?.filter(score => 
      score.special_award_id === awardId
    ) || []
    
    if (!awardVotes.length) return null
    
    // Calculate total scores for each candidate
    const candidateScores = {}
    awardVotes.forEach(vote => {
      if (!candidateScores[vote.candidate_id]) {
        candidateScores[vote.candidate_id] = 0
      }
      candidateScores[vote.candidate_id] += vote.score
    })
    
    // Find candidate with highest score
    const winnerId = Object.keys(candidateScores).reduce((a, b) => 
      candidateScores[a] > candidateScores[b] ? a : b
    )
    
    const winner = event?.candidates?.find(c => c.id === winnerId)
    return winner ? { candidate: winner, score: candidateScores[winnerId] } : null
  }

  const startAnimation = () => {
    if (isAnimating) return
    
    setIsAnimating(true)
    setShowWinner(false)
    setCountdown(3)
    
    const countdownInterval = setInterval(() => {
      setCountdown(prev => {
        if (prev <= 1) {
          clearInterval(countdownInterval)
          setShowWinner(true)
          
          // Get winner data
          let winner = null
          if (displayMode === 'rankings') {
            winner = getWinnerForRanking(selectedRanking)
          } else {
            winner = getWinnerForAward(selectedAward)
          }
          
          setWinnerData(winner)
          setIsAnimating(false)
          return 0
        }
        return prev - 1
      })
    }, 1000)
  }

  const exitFullScreen = () => {
    setIsFullScreen(false)
    setIsAnimating(false)
    setShowWinner(false)
    setCountdown(0)
    setWinnerData(null)
  }

  // Handle spacebar key press
  useEffect(() => {
    const handleKeyPress = (e) => {
      if (e.code === 'Space' && isFullScreen && !isAnimating) {
        e.preventDefault()
        startAnimation()
      }
      if (e.key === 'Escape' && isFullScreen) {
        exitFullScreen()
      }
    }

    if (isFullScreen) {
      document.addEventListener('keydown', handleKeyPress)
      return () => document.removeEventListener('keydown', handleKeyPress)
    }
  }, [isFullScreen, isAnimating])

  const enterFullScreen = () => {
    if (displayMode === 'rankings' && !selectedRanking) {
      toast.error('Please select a ranking position')
      return
    }
    if (displayMode === 'awards' && !selectedAward) {
      toast.error('Please select an award')
      return
    }
    
    setIsFullScreen(true)
  }

  // Awards Functions
  const fetchAwardCategories = async () => {
    try {
      const { data, error } = await supabase
        .from(TABLES.SPECIAL_AWARD_CATEGORIES)
        .select('*')
        .eq('event_id', eventId)
        .order('display_order', { ascending: true })
        .order('created_at', { ascending: true })

      if (error) throw error
      setAwardCategories(data || [])
    } catch (error) {
      console.error('Error fetching award categories:', error)
    }
  }

  const fetchSpecialAwards = async () => {
    try {
      const { data, error } = await supabase
        .from(TABLES.SPECIAL_AWARDS)
        .select(`
          *,
          assigned_candidate:candidates(name, candidate_number, representation)
        `)
        .eq('event_id', eventId)
        .order('display_order', { ascending: true })
        .order('created_at', { ascending: true })

      if (error) throw error
      setSpecialAwards(data || [])

      // Also fetch special award votes for this event
      // We need to get votes through the special_awards table since votes don't have event_id directly
      const { data: votesData, error: votesError } = await supabase
        .from(TABLES.SPECIAL_AWARD_VOTES)
        .select(`
          *,
          special_awards!inner(event_id),
          judges(name, judge_number),
          candidates(name, candidate_number, representation)
        `)
        .eq('special_awards.event_id', eventId)

      if (votesError) {
        console.error('Error fetching special award votes:', votesError)
      } else {
        // Update the event state to include special award votes
        setEvent(prev => prev ? { ...prev, special_award_votes: votesData || [] } : null)
      }
    } catch (error) {
      console.error('Error fetching special awards:', error)
      toast.error('Failed to load special awards')
    }
  }

  const handleAddAward = async () => {
    try {
      const { data, error } = await supabase
        .from(TABLES.SPECIAL_AWARDS)
        .insert({
          event_id: eventId,
          name: newAward.name,
          description: newAward.description,
          award_type: newAward.award_type,
          assigned_candidate_id: newAward.award_type === 'assigned' ? newAward.assigned_candidate_id : null,
          category_id: newAward.category_id || null,
          criteria_id: newAward.award_type === 'criteria_based' ? newAward.criteria_id : null,
          overall_ranking_position: newAward.award_type === 'overall_ranking' ? newAward.overall_ranking_position : null,
          add_to_overall: (newAward.award_type === 'vote' || newAward.award_type === 'assigned') ? newAward.add_to_overall : false,
          overall_points: (newAward.award_type === 'vote' || newAward.award_type === 'assigned') && newAward.add_to_overall ? parseFloat(newAward.overall_points) || 0 : 0
        })
        .select()

      if (error) throw error

      // Log activity
      await logActivity('create', 'award', data[0]?.id, newAward.name, {
        description: `Created ${newAward.award_type} award`,
        award_type: newAward.award_type
      })

      toast.success('Special award created successfully!')
      setShowAddAwardModal(false)
      setNewAward({
        name: '',
        description: '',
        award_type: 'assigned',
        assigned_candidate_id: '',
        category_id: '',
        criteria_id: '',
        overall_ranking_position: '',
        add_to_overall: false,
        overall_points: 0
      })
      await fetchSpecialAwards()
    } catch (error) {
      console.error('Error creating special award:', error)
      toast.error('Failed to create special award')
    }
  }

  const handleEditAward = async () => {
    try {
      const { error } = await supabase
        .from(TABLES.SPECIAL_AWARDS)
        .update({
          name: editingAward.name,
          description: editingAward.description,
          award_type: editingAward.award_type,
          assigned_candidate_id: editingAward.award_type === 'assigned' ? editingAward.assigned_candidate_id : null,
          category_id: editingAward.category_id || null,
          criteria_id: editingAward.award_type === 'criteria_based' ? editingAward.criteria_id : null,
          overall_ranking_position: editingAward.award_type === 'overall_ranking' ? editingAward.overall_ranking_position : null,
          add_to_overall: (editingAward.award_type === 'vote' || editingAward.award_type === 'assigned') ? editingAward.add_to_overall : false,
          overall_points: (editingAward.award_type === 'vote' || editingAward.award_type === 'assigned') && editingAward.add_to_overall ? parseFloat(editingAward.overall_points) || 0 : 0
        })
        .eq('id', editingAward.id)

      if (error) throw error

      // Log activity
      await logActivity('update', 'award', editingAward.id, editingAward.name, {
        description: `Updated ${editingAward.award_type} award`,
        award_type: editingAward.award_type
      })

      toast.success('Special award updated successfully!')
      setShowEditAwardModal(false)
      setEditingAward(null)
      await fetchSpecialAwards()
    } catch (error) {
      console.error('Error updating special award:', error)
      toast.error('Failed to update special award')
    }
  }

  const handleDeleteAward = async (awardId) => {
    if (!window.confirm('Are you sure you want to delete this special award?')) return

    try {
      // Get award details before deleting
      const award = specialAwards.find(a => a.id === awardId)
      
      const { error} = await supabase
        .from(TABLES.SPECIAL_AWARDS)
        .delete()
        .eq('id', awardId)

      if (error) throw error

      // Log activity
      if (award) {
        await logActivity('delete', 'award', awardId, award.name, {
          description: `Deleted ${award.award_type} award`,
          award_type: award.award_type
        })
      }

      toast.success('Special award deleted successfully!')
      await fetchSpecialAwards()
    } catch (error) {
      console.error('Error deleting special award:', error)
      toast.error('Failed to delete special award')
    }
  }

