  // Unified Scoring Sequence Functions
  const handleStartReorderScoringSequence = () => {
    // Build the unified sequence from unlocked criteria and vote-type awards
    const unlockedCriteria = (event.criteria || []).filter(c => !c.is_locked)
    const voteAwards = specialAwards.filter(a => a.award_type === 'vote')
    
    // Check if event has an existing scoring_sequence
    if (event.scoring_sequence && Array.isArray(event.scoring_sequence) && event.scoring_sequence.length > 0) {
      // Use existing sequence but filter out any items that no longer exist
      const validSequence = event.scoring_sequence.filter(item => {
        if (item.type === 'criteria') {
          return unlockedCriteria.some(c => c.id === item.id)
        } else if (item.type === 'award') {
          return voteAwards.some(a => a.id === item.id)
        }
        return false
      }).map(item => {
        if (item.type === 'criteria') {
          const criteria = unlockedCriteria.find(c => c.id === item.id)
          return { type: 'criteria', id: item.id, name: criteria?.name, data: criteria }
        } else {
          const award = voteAwards.find(a => a.id === item.id)
          return { type: 'award', id: item.id, name: award?.name, data: award }
        }
      })
      
      // Add any new items that aren't in the sequence
      const existingIds = validSequence.map(s => s.id)
      const newCriteria = unlockedCriteria
        .filter(c => !existingIds.includes(c.id))
        .map(c => ({ type: 'criteria', id: c.id, name: c.name, data: c }))
      const newAwards = voteAwards
        .filter(a => !existingIds.includes(a.id))
        .map(a => ({ type: 'award', id: a.id, name: a.name, data: a }))
      
      setScoringSequenceOrder([...validSequence, ...newCriteria, ...newAwards])
    } else {
      // Build default sequence: all criteria first (by display_order), then all awards (by display_order)
      const sequence = [
        ...unlockedCriteria.map(c => ({ type: 'criteria', id: c.id, name: c.name, data: c })),
        ...voteAwards.map(a => ({ type: 'award', id: a.id, name: a.name, data: a }))
      ]
      setScoringSequenceOrder(sequence)
    }
    
    setIsReorderingScoringSequence(true)
  }

