  const handleAddCoAdmin = async () => {
    if (!coAdminEmail.trim()) {
      toast.error('Please enter an email address')
      return
    }

    if (!coAdminEmail.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/)) {
      toast.error('Please enter a valid email address')
      return
    }

    setAddingCoAdmin(true)
    try {
      // Check if user exists using RPC function
      const { data: users, error: userError } = await supabase
        .rpc('get_user_id_by_email', { user_email: coAdminEmail.trim().toLowerCase() })

      if (userError) {
        console.error('RPC Error:', userError)
        toast.error('Error looking up user. Please try again.')
        setAddingCoAdmin(false)
        return
      }

      if (!users || users.length === 0) {
        toast.error('User not found. They need to create an account first.')
        setAddingCoAdmin(false)
        return
      }

      const userId = users[0].user_id

      // Check if already a co-admin
      const currentCoAdmins = event.co_admins || []
      if (currentCoAdmins.includes(userId)) {
        toast.error('This user is already a co-admin')
        setAddingCoAdmin(false)
        return
      }

      // Check if trying to add the event owner
      if (userId === event.created_by) {
        toast.error('Event owner is already an admin')
        setAddingCoAdmin(false)
        return
      }

      // Add co-admin
      const { error } = await supabase
        .from(TABLES.EVENTS)
        .update({
          co_admins: [...currentCoAdmins, userId]
        })
        .eq('id', eventId)

      if (error) throw error

      toast.success(`Co-admin added successfully: ${users[0].email_address}`)
      setCoAdminEmail('')
      
      // Log activity
      await logActivity('create', 'co_admin', users[0].id, users[0].email_address, {
        description: `Added co-admin`
      })
      
      await fetchEventData()
    } catch (error) {
      console.error('Error adding co-admin:', error)
      toast.error('Failed to add co-admin')
    } finally {
      setAddingCoAdmin(false)
    }
  }

