  // Add Judge with Password Verification
  const handleAddJudge = async () => {
    if (!judgeActionPassword) {
      setJudgeActionError('Please enter your password to confirm')
      return
    }

    setIsProcessingJudgeAction(true)
    setJudgeActionError('')

    try {
      // Verify password
      const { error: signInError } = await supabase.auth.signInWithPassword({
        email: user.email,
        password: judgeActionPassword,
      })

      if (signInError) {
        setJudgeActionError('Incorrect password. Please try again.')
        setIsProcessingJudgeAction(false)
        return
      }

      // Generate new access code
      const newAccessCode = Math.random().toString(36).substring(2, 10).toUpperCase()
      const newJudgeNumber = event.num_judges + 1

      // Create new judge
      const { error: insertError } = await supabase
        .from(TABLES.JUDGES)
        .insert({
          event_id: eventId,
          judge_number: newJudgeNumber,
          judge_access_code: newAccessCode,
          name: '',
        })

      if (insertError) throw insertError

      // Update event num_judges
      const { error: updateError } = await supabase
        .from(TABLES.EVENTS)
        .update({ num_judges: newJudgeNumber })
        .eq('id', eventId)

      if (updateError) throw updateError

      // Log activity
      await logActivity('create', 'judge', null, `Judge #${newJudgeNumber}`, {
        description: `Added new judge with access code`,
        judge_number: newJudgeNumber,
        access_code: newAccessCode.substring(0, 3) + '***' // Partial code for security
      })

      toast.success(
        <div>
          <div className="font-semibold mb-1">Judge added successfully!</div>
          <div className="text-sm">Access Code: <span className="font-mono font-bold">{newAccessCode}</span></div>
        </div>,
        { duration: 6000 }
      )

      setShowAddJudgeModal(false)
      setJudgeActionPassword('')
      await fetchEventData()
    } catch (error) {
      console.error('Error adding judge:', error)
      toast.error('Failed to add judge')
    } finally {
      setIsProcessingJudgeAction(false)
    }
  }

